// src/components/ai/VoiceEngine.js
// 100% FREE Web Speech API - Voice Recognition

export class VoiceEngine {
  constructor() {
    this.recognition = null;
    this.isListening = false;
    this.silenceTimer = null;
    this.silenceThreshold = 30000; // 30 seconds
    this.onResult = null;
    this.onSilence = null;
    this.onError = null;
    this.transcript = '';
  }

  initialize() {
    // Check browser support
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      console.error('Speech Recognition not supported');
      return false;
    }

    this.recognition = new SpeechRecognition();
    this.recognition.continuous = true;
    this.recognition.interimResults = true;
    this.recognition.lang = 'en-US';

    // Handle results
    this.recognition.onresult = (event) => {
      this.resetSilenceTimer();

      let interimTranscript = '';
      let finalTranscript = '';

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          finalTranscript += transcript + ' ';
        } else {
          interimTranscript += transcript;
        }
      }

      this.transcript = (this.transcript + finalTranscript).trim();

      if (this.onResult) {
        this.onResult({
          final: finalTranscript.trim(),
          interim: interimTranscript,
          full: this.transcript
        });
      }
    };

    // Handle errors
    this.recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      if (this.onError) {
        this.onError(event.error);
      }
    };

    // Handle end
    this.recognition.onend = () => {
      if (this.isListening) {
        // Restart if still supposed to be listening
        this.recognition.start();
      }
    };

    return true;
  }

  start() {
    if (!this.recognition) {
      if (!this.initialize()) {
        return false;
      }
    }

    try {
      this.transcript = '';
      this.isListening = true;
      this.recognition.start();
      this.startSilenceDetection();
      return true;
    } catch (error) {
      console.error('Error starting recognition:', error);
      return false;
    }
  }

  stop() {
    this.isListening = false;
    this.clearSilenceTimer();

    if (this.recognition) {
      try {
        this.recognition.stop();
      } catch (error) {
        console.error('Error stopping recognition:', error);
      }
    }

    const finalTranscript = this.transcript;
    this.transcript = '';
    return finalTranscript;
  }

  startSilenceDetection() {
    this.resetSilenceTimer();
  }

  resetSilenceTimer() {
    this.clearSilenceTimer();

    this.silenceTimer = setTimeout(() => {
      if (this.onSilence) {
        this.onSilence();
      }
    }, this.silenceThreshold);
  }

  clearSilenceTimer() {
    if (this.silenceTimer) {
      clearTimeout(this.silenceTimer);
      this.silenceTimer = null;
    }
  }

  setCallbacks({ onResult, onSilence, onError }) {
    this.onResult = onResult;
    this.onSilence = onSilence;
    this.onError = onError;
  }

  getTranscript() {
    return this.transcript;
  }

  isSupported() {
    return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  }
}
